<?php
require __DIR__.'/includes/bootstrap.php';
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$pdo=database();if(!$pdo){fwrite(STDERR,"Database unavailable. Configure PostgreSQL and pdo_pgsql first.\n");exit(1);}
$email=strtolower(trim(getenv('KABULIG_ADMIN_EMAIL')?:'admin@kabulig.local'));$name=trim(getenv('KABULIG_ADMIN_NAME')?:'Kabulig Admin');$password=getenv('KABULIG_ADMIN_PASSWORD');$generated=false;if(!$password){$password=bin2hex(random_bytes(18));$generated=true;}
$q=$pdo->prepare('SELECT id FROM users WHERE lower(email)=lower(:email)');$q->execute(['email'=>$email]);$id=$q->fetchColumn();if($id){$q=$pdo->prepare("INSERT INTO user_roles(user_id,role_id) SELECT :uid,id FROM roles WHERE code='admin' ON CONFLICT DO NOTHING");$q->execute(['uid'=>$id]);$q=$pdo->prepare("INSERT INTO user_pillar_roles(user_id,pillar_id,role_id,status) SELECT :uid,pillar_id,role_id,'active' FROM pillar_roles ON CONFLICT(user_id,pillar_id,role_id) DO UPDATE SET status='active',updated_at=NOW()");$q->execute(['uid'=>$id]);fwrite(STDOUT,"Administrator role and all pillar access ensured for existing account: {$email}\nNo password was changed.\n");exit;}
$pdo->beginTransaction();try{$q=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(:name,:email,:hash) RETURNING id');$q->execute(['name'=>$name,'email'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$q->fetchColumn();$q=$pdo->prepare("INSERT INTO user_roles(user_id,role_id) SELECT :uid,id FROM roles WHERE code='admin'");$q->execute(['uid'=>$id]);$q=$pdo->prepare("INSERT INTO user_pillar_roles(user_id,pillar_id,role_id,status) SELECT :uid,pillar_id,role_id,'active' FROM pillar_roles");$q->execute(['uid'=>$id]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}
fwrite(STDOUT,"Created administrator account: {$email}\n");if($generated)fwrite(STDOUT,"One-time password: {$password}\nStore it securely; it will not be shown again.\n");else fwrite(STDOUT,"Password taken from KABULIG_ADMIN_PASSWORD.\n");
